import{_ as o,r as t,o as r,c as l,e as s,a as d,s as c}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Record Finder Field - October CMS - 4.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Record Finder"},"headers":[{"level":2,"title":"Usage in Tailor","slug":"usage-in-tailor","link":"#usage-in-tailor","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/element/form/widget-recordfinder.md","filePath":"4.x/element/form/widget-recordfinder.md"}'),i={name:"4.x/element/form/widget-recordfinder.md"};function p(u,e,g,m,h,f){const a=t("pre-heading"),n=t("post-heading");return r(),l("div",null,[s(a),e[0]||(e[0]=d("h1",null,"Record Finder Field",-1)),s(n),e[1]||(e[1]=c(`<p><code>recordfinder</code> - renders a field with details of a related record. Expanding the field displays a popup list to search large amounts of records. Supported by singular relationships only.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">list</span><span class="token punctuation">:</span> ~/plugins/rainlab/user/models/user/columns.yaml
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>keyFrom</strong></td><td>the name of column to use in the relation used for key. Default: <code>id</code>.</td></tr><tr><td><strong>nameFrom</strong></td><td>the column name to use in the relation used for displaying the name. Default: <code>name</code>.</td></tr><tr><td><strong>descriptionFrom</strong></td><td>the column name to use in the relation used for displaying a description. Default: <code>description</code>.</td></tr><tr><td><strong>title</strong></td><td>text to display in the title section of the popup.</td></tr><tr><td><strong>list</strong></td><td>a configuration array or reference to a list column definition file.</td></tr><tr><td><strong>filter</strong></td><td>a reference to a filter scopes definition file, see <a href="./../../extend/lists/filters.html">backend list filters</a>.</td></tr><tr><td><strong>showSetup</strong></td><td>displays a setup button to configure the list columns and records per page. Default: <code>false</code></td></tr><tr><td><strong>structure</strong></td><td>enables a read-only structured list for selecting records, see the <a href="./../../extend/lists/structures.html">sorting records article</a>. Set to <code>false</code> to disable, otherwise enabled when the model uses a tree interface.</td></tr><tr><td><strong>defaultSort</strong></td><td>sets a default sorting column and direction when user preference is not defined. Supports a string or an array with keys <code>column</code> and <code>direction</code>. The direction can be <code>asc</code> for ascending (default) or <code>desc</code> for descending order.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>records to display per page, use 0 for no pages. Default: <code>10</code></td></tr><tr><td><strong>conditions</strong></td><td>specifies a raw where query statement to apply to the list model query.</td></tr><tr><td><strong>modelScope</strong></td><td>applies a <a href="./../../extend/database/model.html">model query scope</a> method to the <strong>related form model</strong>, can be a model method name or a static PHP class method (<code>Class::method</code>). The first argument will contain the model that the widget will be attaching its value to, i.e. the parent model.</td></tr><tr><td><strong>searchMode</strong></td><td>defines the search strategy to either contain all words, any word or exact phrase. Supported options: all, any, exact. Default: <code>all</code>.</td></tr><tr><td><strong>searchScope</strong></td><td>specifies a <a href="./../../extend/database/model.html">model query scope</a> method defined in the <strong>related form model</strong> to apply to the search query, the first argument will contain the search term.</td></tr><tr><td><strong>useRelation</strong></td><td>flag for using the name of the field as a relation name to interact with directly on the parent model. Default: <code>true</code>. Disable to return just the selected model&#39;s ID</td></tr><tr><td><strong>modelClass</strong></td><td>class of the model to use for listing records when <code>useRelation</code> is <code>false</code></td></tr><tr><td><strong>popupSize</strong></td><td>change the size of the finder popup used, either: <code>giant</code>, <code>huge</code>, <code>large</code>, <code>small</code>, <code>tiny</code> or <code>adaptive</code>. Default: <code>huge</code></td></tr><tr><td><strong>inlineOptions</strong></td><td>displays the field with buttons alongside the selected record, disable this mode if horizontal space is limited. Default: <code>true</code>.</td></tr></tbody></table></div><p>You may limit the number of records per page using the <code>recordsPerPage</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">recordsPerPage</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div><p>Use the <code>title</code> property to change the title of the management form.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Find A User
</code></pre></div><p>When a record is selected, the display attributes can be chosen from model attributes using the <code>nameFrom</code> and <code>descriptionFrom</code> properties.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">nameFrom</span><span class="token punctuation">:</span> name
    <span class="token key atrule">descriptionFrom</span><span class="token punctuation">:</span> email
</code></pre></div><p>If a <a href="./../../extend/lists/structures.html">model structure</a> is detected, then the list will display as a structure. This can be disabled or enabled explicitly with the <strong>structure</strong> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">user</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> User
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">structure</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><h2 id="usage-in-tailor"><a href="#usage-in-tailor" class="header-anchor">#</a> Usage in Tailor</h2><p>When the <code>recordfinder</code> field is used as a <a href="./../../cms/tailor/content-fields.html">content field in Tailor</a>, it requires the <code>modelClass</code> property to be specified to define and locate the model relation.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Product
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/october/test/models/product/columns.yaml
</code></pre></div><p>When the <code>maxItems</code> is set to <strong>1</strong>, the relation is defined as a <code>belongsTo</code> relation. Otherwise, the relation is defined as <code>belongsToMany</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">products</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Products
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Tag
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">1</span>
</code></pre></div><p>The <code>inverse</code> property can be set to the relation name on the related model. This will change the relation definition to <code>hasOne</code>, <code>hasMany</code> or <code>belongsToMany</code> based on the <code>maxItems</code> setting and relation type of the related model.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tags</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Tags
    <span class="token key atrule">type</span><span class="token punctuation">:</span> recordfinder
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Test\\Models\\Tag
    <span class="token key atrule">inverse</span><span class="token punctuation">:</span> tags
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../cms/tailor/models.html">Tailor Models</a></li><li><a href="./../../extend/database/relations.html">Database Relations</a></li></ul></div>`,21))])}const b=o(i,[["render",p]]);export{y as __pageData,b as default};
